                        .OnDelete(DeleteBehavior.Cascade)
                        .IsRequired();

                    b.Navigation("ReleaseTask");
                });

            modelBuilder.Entity("Zmg.Domain.Entities.Song", b =>
                {
                    b.HasOne("Zmg.Domain.Entities.Artist", "MainArtist")
