                    b.Navigation("Artist");

                    b.Navigation("Song");
                });

            modelBuilder.Entity("Zmg.Domain.Entities.TemplateTask", b =>
                {
                    b.HasOne("Zmg.Domain.Entities.ChecklistTemplate", "ChecklistTemplate")
